    "עוד אין פעולות ביומן. מהיום כל פעולה רגישה נרשמת כאן.": "No actions in the log yet. From now on every sensitive action is recorded here.",
    "הצג עוד": "Show more",

    // ── stage 3: the longer explanations ──
    "— איתו הוא/היא נכנס/ת ל-BizControl, באפליקציה או באתר, עם הסיסמה שבוחרים כאן. לכל עובד מייל משלו, לא המייל של העסק.": "— they sign in to BizControl with it, in the app or on the site, with the password chosen here. Each staff member has their own email, not the business's.",
    "דוח השכר של הצוות (PDF) וכל המשמרות של החודש בקובץ לאקסל — תאריך, כניסה, יציאה ושעות לכל עובד/ת. סיכום מהמערכת, לא תלוש רשמי: את הניכויים מכין רואה החשבון.": "The team's pay report (PDF) and all the month's shifts in an Excel file — date, clock-in, clock-out and hours for each staff member. A summary from the system, not an official payslip: the accountant prepares the deductions.",
    "העובדים והמנהלים מחתימים כניסה ויציאה בכפתור \"כניסה\" שבראש המסך. רוצים ברקוד או מדבקה בכניסה, כדי שיחתימו רק כשהם באמת בעסק? פנו ל-BizControl.": "Staff and managers clock in and out with the \"Clock in\" button at the top of the screen. Want a barcode or a sticker at the door, so they clock in only when they're really at the business? Contact BizControl.",
    "העובדים והמנהלים מחתימים כניסה ויציאה בטלפון שלהם: סורקים במצלמה את הברקוד שתלוי בכניסה (או נוגעים במדבקה). כל אחד מחובר לחשבון שלו — כך המערכת יודעת מי נכנס ומי יצא. השעות נרשמות, ומי שמשולם לפי שעות — מקבל לפיהן.": "Staff and managers clock in and out on their own phones: they scan the barcode hanging at the door with the camera (or touch the sticker). Each is signed in to their own account — that's how the system knows who came and who left. The hours are recorded, and those paid by the hour are paid by them.",
    "הברקוד עובד: עובד או מנהל שסורקים אותו מהטלפון שלהם נרשמים לכניסה, ובסריקה הבאה ליציאה. בעל העסק לא מחתים שעון.": "The barcode works: staff or a manager scanning it from their phone are clocked in, and on the next scan clocked out. The owner doesn't clock in.",
    "ללקוח אחרי הביקור הראשון, פעם אחת, או ידנית מתיק הלקוח — רק אחרי שאפליקציית BizFind ב-App Store": "To a client after the first visit, once, or by hand from the client's file — only once the BizFind app is in the App Store",
    "כאן בוחרים אילו הודעות יוצאות ללקוחות ומה כתוב בהן. כל הודעה נשלחת בוואטסאפ — ואם ללקוח יש מייל, אותו טקסט נשלח גם למייל.": "Here you choose which messages go out to clients and what they say. Each message is sent on WhatsApp — and if the client has an email, the same text goes by email too.",
    "נשלח הנוסח של המערכת — עם הפרטים של כל לקוח ותור. רוצה נוסח משלך? לחצו \"עריכת הנוסח\".": "The system's wording is sent — with each client's and appointment's details. Want your own wording? Tap \"Edit the wording\".",
    "מי עשה מה ומתי: קבלות וזיכויים, מחיקות, הנחות בקופה, שינויי הגדרות, הצוות ותיקוני נוכחות. רק אתה רואה את היומן.": "Who did what and when: receipts and credit notes, deletions, register discounts, settings changes, the team and attendance fixes. Only you see the log.",

    // ── stage 3: the activity log's areas (app/services/activity_log.AREAS) ──
    "קבלות וזיכויים": "Receipts & credits",
