    "Aftercare — עיכוב הודעה": "Aftercare — message delay",
    "מספר הדקות אחרי שעת התור שאחריהן נשלחת הודעת הטיפול. ברירת מחדל: 30 דקות. המלצה: 60–120 דקות.": "The minutes after the appointment time before the care message goes out. Default: 30 minutes. Recommended: 60–120 minutes.",
    "שעת פתיחה וסגירה ביומן (ברירת מחדל: 08:00–23:00). לא מונע תורים מחוץ לשעות — רק קובע תצוגה.": "The calendar's opening and closing time (default: 08:00–23:00). It doesn't prevent appointments outside the hours — it only sets the view.",
    "הגדרות — תשלומים ופיננסים": "Settings — payments and finance",
