    "תהליך": "The flow",
    "נוצר תור עם מקדמה ← הלקוח מקבל הודעת וואטסאפ עם לינק.": "An appointment with a deposit is created → the client gets a WhatsApp message with a link.",
    "הלקוח פותח את הלינק ← רואה פרטי תור וסכום מקדמה.": "The client opens the link → sees the appointment details and the deposit amount.",
    "הלקוח משלם דרך ביט/פייבוקס (לינקים שהוגדרו בהגדרות).": "The client pays through Bit/Paybox (the links set in settings).",
