    "ידולגו": "will be skipped",
    "לקוחות שביקשו להסיר את עצמם (בקישור ההסרה או בתשובת \"הסר\" בוואטסאפ), שכיבית להם בכרטיס, או שלא אישרו בהרשמה. הם לא מקבלים תפוצות, הזמנות למועדון וקופוני יום הולדת — אבל אישורי תור, תזכורות וקבלות ממשיכים להגיע אליהם.": "Clients who asked to be removed (through the unsubscribe link or by replying \"stop\" on WhatsApp), whom you turned off in their card, or who didn't agree at sign-up. They don't get broadcasts, club invitations or birthday coupons — but booking confirmations, reminders and receipts still reach them.",
    "הקובץ כולל פרטים אישיים של הלקוחות — שמרו אותו במקום בטוח. כל ייצוא נרשם ביומן הפעילות. באפליקציה בטלפון — השתמשו ב\"שליחה למייל\".": "The file includes clients' personal details — keep it somewhere safe. Every export is recorded in the activity log. In the phone app — use \"Send to my email\".",
    "כמות": "Quantity",
    "שום דבר לא נכתב למערכת לפני שתראה תצוגה מקדימה ותאשר. כפילויות מזוהות ומוצגות לך להחלטה, לקוחות לא מקבלים הודעות, ואפשר לבטל ייבוא גם אחרי שרץ.": "Nothing is written to the system before you see a preview and confirm. Duplicates are found and shown to you to decide, clients get no messages, and an import can be undone even after it ran.",
    "מ-Arbox, קלמארק או כל מערכת אחרת: ייצא מתוכה את רשימת הלקוחות (או השירותים) לקובץ Excel או CSV והעלה אותו כאן. חיבור ישיר למערכות האלה יתווסף בהמשך.": "From Arbox, Calmark or any other system: export its client (or service) list to an Excel or CSV file and upload it here. A direct connection to those systems will come later.",
