    "מדפיסים ותולים בכניסה. הלקוח סורק בטלפון ומסומן/ת \"הגיע/ה\" לשיעור שנרשם/ה אליו. מתי אפשר לסרוק ומה קורה כשאין הרשמה — בלשונית הכללים, תחת \"צ׳ק-אין בכניסה\".": "Print it and hang it at the door. The client scans it with their phone and is marked \"attended\" for the class they signed up for. When scanning is allowed and what happens without a sign-up — in the rules tab, under \"Check-in at the door\".",
