    // ── what not renewing means (lib/planConsequences) ──
    "המערכת — יומן, לקוחות, תשלומים והגדרות — תיחסם, ותוצג רק הודעה על סיום המנוי.": "The system — calendar, clients, payments and settings — will be locked, showing only a notice that the subscription ended.",
    "אתר העסק יעבור לארכיון: דף הנחיתה, הזמנת תורים אונליין, רשימת ההמתנה, ההצטרפות למועדון וחנות כרטיסי המתנה יפסיקו לקבל לקוחות. מי שיכנס יראה שהעסק אינו זמין להזמנות.": "The business's site will be archived: the landing page, online booking, the waiting list, club sign-up and the gift card store will stop taking clients. Visitors will see the business isn't taking bookings.",
    "העסק יוסתר מהחיפוש ב-BizFind.": "The business will be hidden from BizFind's search.",
    "שום דבר לא נמחק: הלקוחות, היומן, ההיסטוריה והתשלומים נשמרים.": "Nothing is deleted: the clients, the calendar, the history and the payments are kept.",
    "אחרי החידוש הכול חוזר לפעול מעצמו — הכניסה למערכת, האתר וקביעת התורים.": "After renewing everything works again by itself — signing in, the site and booking.",
    "המערכת — יומן, לקוחות, תשלומים והגדרות — חסומה, ומוצגת רק הודעה על סיום המנוי.": "The system — calendar, clients, payments and settings — is locked, showing only a notice that the subscription ended.",
    "אתר העסק בארכיון: דף הנחיתה, הזמנת תורים אונליין, רשימת ההמתנה, ההצטרפות למועדון וחנות כרטיסי המתנה אינם מקבלים לקוחות. מי שנכנס רואה שהעסק אינו זמין להזמנות.": "The business's site is archived: the landing page, online booking, the waiting list, club sign-up and the gift card store aren't taking clients. Visitors see the business isn't taking bookings.",
    "העסק מוסתר מהחיפוש ב-BizFind.": "The business is hidden from BizFind's search.",
    "ברגע שהמנוי יחודש הכול חוזר לפעול מעצמו — הכניסה למערכת, האתר וקביעת התורים.": "Once the subscription is renewed everything works again by itself — signing in, the site and booking.",

